[entities]
;; The switchback: from the third ledge (21) up the right wall to the fourth (12).
vine 14 20 len=12
;; The way out: from the top ledge (6) up off the top of the screen.
vine 1 5 len=8

[zones]
;; Climbing the left vine off the top: 7-3 at 199, onto the tree platform past the bridge.
vine 1 5 -> 7-3 199 12

